query:
-- Total active leads (everything except Lost)
SELECT COUNT(*) as active_leads FROM leads WHERE stage != 'Lost';

-- All leads by stage
SELECT stage, COUNT(*) as count FROM leads GROUP BY stage ORDER BY count DESC;

